  "output": "// Day boundaries and words are computed in the viewer's own timezone
// (the browser's resolved timezone). The server only sends raw
// timestamps; rendering happens here so HTML can be shared between people.
export function signedDifferenceInDays(fromDate, toDate) {
  return Math.round((beginningOfDay(toDate) - beginningOfDay(fromDate)) / (1000 * 60 * 60 * 24))
}

export function beginningOfDay(date) {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate())
}

export function formatTime(date) {
  return timeFormatter().format(date)
}

export function formatDate(date, now = new Date()) {
  if (date.getFullYear() === now.getFullYear()) {
    return shortDateFormatter().format(date)
  } else {
    return fullDateFormatter().format(date)
  }
}

export function formatFullDate(date) {
  return fullDateFormatter().format(date)
}

export function formatWeekdayDate(date) {
  return weekdayDateFormatter().format(date)
}

export function formatShortDatetime(date) {
  return `${shortDateNumericFormatter().format(date)}, ${formatTime(date)}`
}

// Backwards-compatible aliases
export const formatDatetime = formatShortDatetime
export const formatDateTime = formatShortDatetime
export const formatWeekday = formatWeekdayDate

export function formatFullDatetime(date) {
  return fullDatetimeFormatter().format(date)
}

// Hybrid relative words in the viewer's timezone:
//
//   today (same calendar day)      -> "1:42 PM"
//   yesterday                      -> "yesterday"
//   tomorrow                       -> "tomorrow"
//   2-6 days in the past           -> "5 days ago"
//   2-6 days in the future         -> "in 3 days"
//   7+ days away                   -> "Sep 12" (with year when different year)
//
export function formatRelative(date, now = new Date()) {
  const diff = signedDifferenceInDays(now, date)

  if (diff === 0) {
    return formatTime(date)
  } else if (diff === -1) {
    return "yesterday"
  } else if (diff === 1) {
    return "tomorrow"
  } else if (diff < -1 && diff >= -6) {
    return `${-diff} days ago`
  } else if (diff > 1 && diff <= 6) {
    return `in ${diff} days`
  } else {
    return formatDate(date, now)
  }
}

