import { Controller } from "@hotwired/stimulus"
import { formatWithStyle, formatFullDatetime } from "helpers/date_helpers"

// Renders a server-provided timestamp in the viewer's own timezone.
//
// The server emits shareable markup:
//
//   <time datetime="2025-09-12T13:42:00Z" data-controller="time" data-time-format-value="relative">Sep 12</time>
//
// and this controller turns it into local words:
//
//   today      -> "1:42 PM"
//   yesterday  -> "yesterday"
//   5 days ago -> "5 days ago" (or "Sep 12" for date formats)
//   tomorrow   -> "tomorrow"
//   in 3 days  -> "in 3 days"
//
export default class extends Controller {
  static values = { format: String }

  connect() {
    this.render()
  }

  formatValueChanged() {
    this.render()
  }

  render() {
    const datetime = this.element.getAttribute("datetime") || this.element.getAttribute("datetime-value") || this.element.dataset.datetime
    if (!datetime) return

    const date = new Date(datetime)
    if (isNaN(date.getTime())) return

    const style = this.#style
    const text = formatWithStyle(date, style, new Date())
    if (text) this.element.textContent = text

    try {
      this.element.setAttribute("title", formatFullDatetime(date))
    } catch {
      // ignore title failures
    }

    this.#syncBridgeDescription(date)
  }

  get #style() {
    if (this.hasFormatValue && this.formatValue) return this.formatValue
    return this.element.getAttribute("data-local") ||
      this.element.getAttribute("data-format") ||
      this.element.dataset.format ||
      "relative"
  }

  // Keep native bridge descriptions in the viewer's timezone too. The server
  // renders them in UTC for shareable caches; when the visible <time> inside
  // a stamp renders locally, mirror the local date onto the ancestor so the
  // native side receives the viewer's words.
  #syncBridgeDescription(date) {
    const stamped = this.element.closest("[data-bridge-description]")
    if (!stamped) return

    try {
      const { formatFullDate } = requireFormatFullDate()
      stamped.setAttribute("data-bridge-description", formatFullDate(date))
    } catch {
      // Fallback: leave server value; formatting still correct in the browser
    }
  }
}

function requireFormatFullDate() {
  // Avoid a static import cycle; date_helpers already provides this.
  // This indirection keeps the controller small while reusing formatting.
  let cached
  return cached ||= importFormatFullDate()
}

function importFormatFullDate() {
  // Lazily reference the already-imported module scope via dynamic lookup.
  // In practice we just format here to avoid async imports:
  return {
    formatFullDate(date) {
      return new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric", year: "numeric" }).format(date)
    }
  }
}
