require "application_system_test_case"

class EdgeTimeTest < ApplicationSystemTestCase
  test "relative formatting edge cases" do
    sign_in_as(users(:david))
    visit root_path

    # Test JS formatting directly by injecting time elements
    results = page.evaluate_script(<<~JS)
      (function() {
        // Import not available in evaluate_script, so replicate logic? Instead test via creating time tags and waiting for formatter
        // We'll create time tags with known datetimes and let our initializer format them
        const now = new Date();
        const tests = [];

        function isoForOffsetDays(offsetDays, hour=13, minute=42) {
          const d = new Date(now);
          d.setDate(d.getDate() + offsetDays);
          d.setHours(hour, minute, 0, 0);
          return d.toISOString();
        }

        const cases = [
          { name: "today 2h ago", iso: new Date(now.getTime() - 2*60*60*1000).toISOString() },
          { name: "yesterday", iso: isoForOffsetDays(-1) },
          { name: "5 days ago", iso: isoForOffsetDays(-5) },
          { name: "10 days ago", iso: isoForOffsetDays(-10) },
          { name: "tomorrow", iso: isoForOffsetDays(1) },
          { name: "in 3 days", iso: isoForOffsetDays(3) },
          { name: "in 10 days", iso: isoForOffsetDays(10) },
        ];

        const container = document.createElement("div");
        container.id = "test-times";
        document.body.appendChild(container);

        cases.forEach(c => {
          const el = document.createElement("time");
          el.setAttribute("datetime", c.iso);
          el.setAttribute("data-controller", "time");
          el.setAttribute("data-time-format-value", "relative");
          el.textContent = "pending";
          el.id = "test-" + c.name.replace(/\\s+/g, "-");
          container.appendChild(el);
        });

        return cases.map(c => c.iso);
      })()
    JS
    puts "ISOs: #{results}"
    sleep 2
    texts = page.evaluate_script(<<~JS)
      (function() {
        const els = document.querySelectorAll("#test-times time");
        return Array.from(els).map(el => ({ id: el.id, datetime: el.getAttribute("datetime"), text: el.textContent, title: el.getAttribute("title") }));
      })()
    JS
    puts "Formatted:"
    texts.each { |t| puts t.inspect }

    # Check expectations (raw textContent, before CSS transform - but these are in body, no CSS transform)
    # Today should be time like "1:42 PM" or similar (depends on now)
    # Yesterday should be "yesterday"
    # 5 days ago should be "5 days ago"
    # 10 days ago should be like "Sep 1" (date)
    # Tomorrow should be "tomorrow"
    # In 3 days should be "in 3 days"
    # In 10 days should be date
  end
end
ENDOFFILE
cp /tmp/edge_test.rb test/system/edge_time_test.rb
